// Not a test file: synthetic run data (generated by code, no game output) for the evaluation and report tests and the
// fake driver's dead / cleared modes (#99). Shapes follow game/tools/playtest/playtest_timeline.gd (timeline.jsonl
// rows, hits.jsonl lines) and balance_run.gd run_one (the round record).

export type Row = Record<string, number | string>;
export type Hit = { time: number; tick: number; damage: number; max_hp: number; fraction: number; source: string; boss: boolean;
	mob_id: number; tier?: number };

/** A 64.5 s round that dies 4.5 s after a boss arrives at 60 s: three boss contact hits of 40% each, a calm first
 * minute with kills and level-ups, the tactic aggressive throughout. */
export function deadRun() {
	const timeline: Row[] = [];
	for (let t = 1; t <= 64; t++) {
		const hp = t < 61 ? 100 : t < 63 ? 60 : 20;
		timeline.push({ time: t, tick: t * 60, hp, max_hp: 100, mp: 30, max_mp: 50, level: 1 + Math.floor(t / 20),
			exp: t, alive: 6, near: t < 60 ? 1 : 3, bosses: t >= 60 ? 1 : 0, x: 400 + t, y: 215, platform: 16,
			tactic: "aggressive", state: "PLAYING", kills: t * 2, drops: 2, drops_above: 0, potions_hp: 5 });
	}
	const hit = (time: number, fraction: number, boss: boolean, source: string): Hit => ({ time, tick: Math.round(time * 60),
		damage: Math.round(fraction * 100), max_hp: 100, fraction, source, boss, mob_id: boss ? 2220000 : 100100 });
	const hits: Hit[] = [hit(20.5, 0.06, false, "touch"), hit(60.8, 0.4, true, "touch"), hit(62.4, 0.4, true, "touch"),
		hit(64.5, 0.4, true, "touch")];
	const record = {
		state: "DEAD", time: 64.5, level: 4, job: 0, kills: 128, timeout: false, seed: 1, stage: "henesys_hg1",
		reach: {}, job_t: -1, level_by_min: [3], hits_by_min: [1], kills_by_min: [120],
		potions_collected: { hp: 0, mp: 0 }, potions_used: { hp: 0, mp: 0 }, potions_left: { hp: 5, mp: 0 },
		potion_uses: [], mp_short_seconds: 0,
		boss_fights: [{ boss_index: 0, mob_id: 2220000, spawn_time: 60, death_time: -1, duration: -1, elapsed: 4.5, status: "alive" },
			{ boss_index: 1, mob_id: 6130101, spawn_time: -1, death_time: -1, duration: -1, elapsed: 0, status: "not_spawned" }],
		boss_hits: hits.filter((h) => h.boss).map((h) => ({ mob_id: h.mob_id, time: h.time, damage: h.damage, max_hp: 100,
			fraction: h.fraction, mp_absorbed: 0, source_kind: h.source })),
		camper: { portals: [] }, start_character: { level: 1, job_id: 0 },
		tactics: { seconds: { aggressive: 64.5 }, shares: { aggressive: 1 }, switches: 0, decisions: 9, platforms_visited: 1 },
		cards_taken: ["2:three_snails_count", "3:three_snails_pierce"],
	};
	return { timeline, hits, record };
}

/** A 150 s round that clears: busy every minute, a boss arrives at 60 s and dies at 125 s. */
export function clearedRun() {
	const timeline: Row[] = [];
	const platforms = [16, 7, 3, 9];
	for (let t = 1; t <= 150; t++) {
		timeline.push({ time: t, tick: t * 60, hp: 90, max_hp: 100, mp: 40, max_mp: 50, level: 1 + Math.floor(t / 10),
			exp: t, alive: 20, near: 4, bosses: t >= 60 && t < 125 ? 1 : 0, x: 100 + (t % 40) * 20, y: 215,
			platform: platforms[Math.floor(t / 20) % platforms.length], tactic: t % 30 < 20 ? "kite" : "collect",
			state: t === 150 ? "CLEARED" : "PLAYING", kills: t * 3, drops: 1, drops_above: 0, potions_hp: 4 });
	}
	const hits: Hit[] = [10, 40, 70, 100, 130].map((time) => ({ time, tick: time * 60, damage: 8, max_hp: 100, fraction: 0.08,
		source: "touch", boss: false, mob_id: 100100 }));
	const record = {
		state: "CLEARED", time: 150, level: 16, job: 200, kills: 450, timeout: false, seed: 2, stage: "henesys_hg1",
		reach: { "8": 75.2, "10": 95.1 }, job_t: 95.1, level_by_min: [7, 13], hits_by_min: [2, 2], kills_by_min: [180, 360],
		potions_collected: { hp: 2, mp: 1 }, potions_used: { hp: 1, mp: 1 }, potions_left: { hp: 4, mp: 0 }, potion_uses: [],
		mp_short_seconds: 3.5,
		boss_fights: [{ boss_index: 0, mob_id: 2220000, spawn_time: 60, death_time: 125, duration: 65, elapsed: 65, status: "dead" }],
		boss_hits: [], camper: { portals: ["up00"] }, start_character: { level: 1, job_id: 0 },
		tactics: { seconds: { kite: 100, collect: 50 }, shares: { kite: 0.667, collect: 0.333 }, switches: 8, decisions: 19,
			platforms_visited: 4 },
		cards_taken: ["2:three_snails_count", "5:magic_claw_new"],
	};
	return { timeline, hits, record };
}

/** A card decision record with the meaningfulness Score the Jev brain records (#94). */
export function cardDecision(id: number, time: number, score: number, confidence: number) {
	return { id, kind: "card", tick: Math.round(time * 60), time, options: ["a_rank", "b_rank", "c_new"], baseline: "a_rank",
		answer: "b_rank", source: "jev", confidence: 0.5, latency_ms: 90,
		meaningfulness: { score, confidence, probabilities: {}, levels: 4 } };
}
